extension DeclReferenceExprSyntax {
  /// If this declaration reference is a simple identifier, return that
  /// string.
  var simpleIdentifier: Identifier? {
    guard argumentNames == nil else {
      return nil
    }

    return baseName./*c*/identifier
  }
}
